import math
import numpy as np

def tail_count(x, k):
    x = np.asarray(x, dtype=float)
    s = x.std(ddof=1)
    return int(np.sum(np.abs(x - x.mean()) > k * s))

def normal_tail_expected(n, k):
    phi = 0.5 * (1 + math.erf(k / math.sqrt(2)))   # P(Z <= k)
    return n * 2 * (1 - phi)
